CompletableFuture<Integer> total =
    loadIds().thenCompose(ids ->
        CompletableFuture.supplyAsync(() -> ids.size())
            .thenApply(n -> n * 2)
            .thenApply(n -> { check(n); return n; }));   // each stage is a continuation

// stackless recursion without stack growth, because each stage returns a future
CompletableFuture<Integer> sum(int i, CompletableFuture<Integer> acc) {
    return i == 0 ? acc : sum(i - 1, acc.thenApply(a -> a + i));
}
